cat > s2.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:60598/login');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForURL('**/dashboard');
await p.waitForTimeout(4000);
console.log(await p.evaluate(()=>document.body.innerText));
console.log(await p.evaluate(()=>Array.from(document.querySelectorAll('*')).filter(e=>e.children.length==0 && /Open invoices/i.test(e.textContent)).map(e=>e.outerHTML+' | parent: '+e.parentElement.innerText).join('\n')));
await b.close();
EOF
